)
SELECT (SELECT count(*) FROM st) AS state_rows, (SELECT count(*) FROM sup) AS suppression_rows, (SELECT count(*) FROM ob) AS cancelled_messages, (SELECT count(*) FROM rs) AS revival_stopped

