    handoff_reason = CASE WHEN $2 = 'handoff' THEN NULLIF($6, '') ELSE NULL END, disqualify_reason = CASE WHEN $2 = 'disqualified' THEN NULLIF($6, '') ELSE NULL END, updated_at = now()
  WHERE contact_id = $1 RETURNING contact_id
), m AS (
